  return n * 3;
}

// rewrite triple as an arrow function, then add isPositive

console.log(triple(4));
console.log(isPositive(-2));

tasks.solution:
// rewrite triple as an arrow function, then add isPositive
const triple = (n) => n * 3;
const isPositive = (n) => n > 0;

console.log(triple(4));
console.log(isPositive(-2));

