tasks.solution:
let message = "Speed is normal.";
const speed = 120;

if (speed > 100) {
  message = "Too fast!";
}

console.log(message);

let fuel = 40;
// write the addFuel arrow function and call it twice with 25
const addFuel = (amount) => {
  fuel += amount;
  return fuel;
};
addFuel(25);
addFuel(25);

console.log("Fuel:", fuel);

tasks.starter:
const repeat = (times, action) => {
  // call action with every number from 1 to times
};

repeat(3, (n) => console.log(`Round ${n}`));

tasks.solution:
const repeat = (times, action) => {
  // call action with every number from 1 to times
  for (let i = 1; i <= times; i++) {
    action(i);
  }
};

repeat(3, (n) => console.log(`Round ${n}`));

