project_task.solution:
function makeCounter(step = 1) {
  let count = 0;
  return () => {
    count += step;
    return count;
  };
}

const countStar = makeCounter();
const addScore = makeCounter(10);
let stars = 0;
let score = 0;

// collect 3 stars: every round stars = countStar(); score = addScore();
for (let i = 0; i < 3; i++) {
  stars = countStar();
  score = addScore();
}

console.log(`Stars: ${stars} | Score: ${score}`);
